diff --git a/repro/no-lonely-if-19033.js b/repro/no-lonely-if-19033.js
new file mode 100644
index 0000000..0fa6039
--- /dev/null
+++ b/repro/no-lonely-if-19033.js
@@ -0,0 +1,47 @@
+"use strict";
+
+// Reproduction for no-lonely-if unsafe autofix (dangling else).
+const assert = require("node:assert");
+const path = require("node:path");
+
+// Set ESLINT_PKG to an installed eslint package dir to test a published release instead of this checkout.
+const eslintPath = process.env.ESLINT_PKG ? path.resolve(process.env.ESLINT_PKG) : path.join(__dirname, "..");
+const { Linter } = require(eslintPath);
+
+console.log(`eslint ${require(path.join(eslintPath, "package.json")).version} from ${eslintPath}`);
+
+const code = [
+    "if (true)",
+    "\tif (false) {}",
+    "\telse { if (false) {} }",
+    "else throw Error('This `else` should have been unreachable!');",
+    ""
+].join("\n");
+
+const linter = new Linter();
+const config = { rules: { "no-lonely-if": "error" } };
+
+console.log("Messages:", linter.verify(code, config).map(m => `${m.line}:${m.column} ${m.message}`));
+
+const { output } = linter.verifyAndFix(code, config);
+
+console.log("--- input ---\n" + code);
+console.log("--- fixed ---\n" + output);
+
+function run(src) {
+    try {
+        new Function(src)(); // eslint-disable-line no-new-func -- evaluate snippet
+        return "ok";
+    } catch (e) {
+        return `threw: ${e.message}`;
+    }
+}
+
+const before = run(code);
+const after = run(output);
+
+console.log("input runtime :", before);
+console.log("fixed runtime :", after);
+
+assert.strictEqual(after, before, "BUG: no-lonely-if autofix changed program behavior (outer `else` was captured by the un-braced inner `if`)");
+console.log("PASS: fix preserved behavior");
diff --git a/repro/no-lonely-if-fuzz.js b/repro/no-lonely-if-fuzz.js
new file mode 100644
index 0000000..a20de0e
--- /dev/null
+++ b/repro/no-lonely-if-fuzz.js
@@ -0,0 +1,60 @@
+"use strict";
+
+// Generates random nested if/else code and checks that no-lonely-if's autofix preserves behavior.
+const path = require("node:path");
+const eslintPath = process.env.ESLINT_PKG ? path.resolve(process.env.ESLINT_PKG) : path.join(__dirname, "..");
+const { Linter } = require(eslintPath);
+const linter = new Linter();
+const config = { rules: { "no-lonely-if": "error" } };
+
+let seed = Number(process.env.SEED || 1);
+const rand = n => {
+    seed = (seed * 1103515245 + 12345) % 2147483648;
+    return seed % n;
+};
+let id = 0;
+
+function stmt(depth) {
+    const r = depth > 3 ? 0 : rand(7);
+    const c = () => `t(${id++})`;
+
+    switch (r) {
+        case 0: return `log(${id++});`;
+        case 1: return `if (${c()}) ${stmt(depth + 1)}`;
+        case 2: return `if (${c()}) ${stmt(depth + 1)} else ${stmt(depth + 1)}`;
+        case 3: return `if (${c()}) ${stmt(depth + 1)} else { if (${c()}) ${stmt(depth + 1)} }`;
+        case 4: return `if (${c()}) ${stmt(depth + 1)} else { if (${c()}) ${stmt(depth + 1)} else ${stmt(depth + 1)} }`;
+        case 5: return `for (let i = 0; i < 1; i++) ${stmt(depth + 1)}`;
+        default: return `{ ${stmt(depth + 1)} }`;
+    }
+}
+
+function trace(src, bits) {
+    const out = [];
+
+    new Function("t", "log", src)(n => (bits >> (n % 16)) & 1, n => out.push(n)); // eslint-disable-line no-new-func -- run snippet
+    return out.join(",");
+}
+
+const iterations = Number(process.env.N || 20000);
+let fixedCount = 0;
+
+for (let i = 0; i < iterations; i++) {
+    id = 0;
+    const code = `${stmt(0)}\n`;
+    const { output, fixed } = linter.verifyAndFix(code, config);
+
+    if (!fixed) {
+        continue;
+    }
+    fixedCount++;
+    for (let bits = 0; bits < 64; bits++) {
+        const a = trace(code, bits), b = trace(output, bits);
+
+        if (a !== b) {
+            console.log(`MISMATCH (t-bits=${bits}): ${a} vs ${b}\n--- input ---\n${code}--- fixed ---\n${output}`);
+            process.exit(1);
+        }
+    }
+}
+console.log(`no mismatch in ${iterations} programs (${fixedCount} were autofixed)`);
